using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using LighFight.Runtime;
public static class UniqueDanceExactGenericSetup {
 const string Folder="Assets/UniqueDancesReview/Fighter-9",Source="Assets/UniqueDancesReview/GenericSources/action-74.fbx";
 static readonly string[] Names={"Hips","Spine02","Spine01","Spine","neck","Head","LeftShoulder","LeftArm","LeftForeArm","LeftHand","RightShoulder","RightArm","RightForeArm","RightHand","LeftUpLeg","LeftLeg","LeftFoot","LeftToeBase","RightUpLeg","RightLeg","RightFoot","RightToeBase"};
 static readonly HumanBodyBones[] Human={HumanBodyBones.Hips,HumanBodyBones.Spine,HumanBodyBones.Chest,HumanBodyBones.UpperChest,HumanBodyBones.Neck,HumanBodyBones.Head,HumanBodyBones.LeftShoulder,HumanBodyBones.LeftUpperArm,HumanBodyBones.LeftLowerArm,HumanBodyBones.LeftHand,HumanBodyBones.RightShoulder,HumanBodyBones.RightUpperArm,HumanBodyBones.RightLowerArm,HumanBodyBones.RightHand,HumanBodyBones.LeftUpperLeg,HumanBodyBones.LeftLowerLeg,HumanBodyBones.LeftFoot,HumanBodyBones.LeftToes,HumanBodyBones.RightUpperLeg,HumanBodyBones.RightLowerLeg,HumanBodyBones.RightFoot,HumanBodyBones.RightToes};
 static readonly int[] Child={1,2,3,4,5,-1,7,8,9,-1,11,12,13,-1,15,16,17,-1,19,20,21,-1};
 public static void Run(){
  UniqueDanceGenericSourceAudit.Run();
  var original=AssetDatabase.LoadAssetAtPath<GameContent>("Assets/LighFight/Content/GameContent.asset").fighters[9];var actor=(GameObject)PrefabUtility.InstantiatePrefab(original);var source=AssetDatabase.LoadAssetAtPath<GameObject>(Source);
  try{
   var animator=actor.GetComponentInChildren<Animator>();var nodes=animator.GetComponentsInChildren<Transform>(true);var oldP=nodes.Select(t=>t.localPosition).ToArray();var oldQ=nodes.Select(t=>t.localRotation).ToArray();var oldS=nodes.Select(t=>t.localScale).ToArray();
   var root=Clone(source.transform,actor.transform);root.name="ExactDanceSource";
   var component=actor.AddComponent<ExactGenericDanceRetarget>();component.source=AssetDatabase.LoadAssetAtPath<NativeSupportPoseData>(Folder+"/Dance.generic.source.pose.asset");component.sourceRoot=root;component.targetAnimator=animator;component.grounding=actor.GetComponent<CandidateFootGrounding>();component.sourceMapped=Names.Select(n=>root.GetComponentsInChildren<Transform>(true).Single(t=>t.name==n)).ToArray();component.targetMapped=Human.Select(h=>animator.GetBoneTransform(h)).ToArray();component.targetNodes=nodes;
   var sb=component.sourceMapped;var tb=component.targetMapped;Quaternion inverse=Quaternion.Inverse(actor.transform.rotation);component.bodyAlignment=(inverse*Basis(tb[14],tb[18],tb[5],tb[0]))*Quaternion.Inverse(inverse*Basis(sb[14],sb[18],sb[5],sb[0]));component.sourceRestRotations=sb.Select(t=>inverse*t.rotation).ToArray();component.sourceHipRest=actor.transform.InverseTransformPoint(sb[0].position);
   // Derived canonical T-pose only: anatomical source segment directions determine
   // animated rotations. Bind matrices, source/target assets and Avatar are untouched.
   for(int b=0;b<tb.Length;b++){int child=Child[b];if(child<0)continue;Vector3 desired=actor.transform.rotation*component.bodyAlignment*(inverse*(sb[child].position-sb[b].position));Vector3 current=tb[child].position-tb[b].position;if(desired.sqrMagnitude<1e-10||current.sqrMagnitude<1e-10)throw new Exception("Degenerate canonical segment");tb[b].rotation=Quaternion.FromToRotation(current,desired)*tb[b].rotation;}
   component.targetCanonicalRotations=tb.Select(t=>inverse*t.rotation).ToArray();component.targetLocalPositions=nodes.Select(t=>t.localPosition).ToArray();component.targetLocalRotations=nodes.Select(t=>t.localRotation).ToArray();component.targetLocalScales=nodes.Select(t=>t.localScale).ToArray();component.targetHipRest=actor.transform.InverseTransformPoint(tb[0].position);
   component.hipHeightScale=(tb[0].position.y-(tb[16].position.y+tb[20].position.y)*.5f)/(sb[0].position.y-(sb[16].position.y+sb[20].position.y)*.5f);if(component.hipHeightScale<=0)throw new Exception("Invalid canonical height scale");
   var overlay=actor.GetComponent<NativeSupportOverlay>();overlay.entries=overlay.entries.Where(e=>e.state!="Dance").ToArray();component.nativeCorrectionCap=overlay.nativeMaxCorrection;component.inactiveCorrectionCap=overlay.baseMaxCorrection;
   animator.runtimeAnimatorController=AssetDatabase.LoadAssetAtPath<UnityEditor.Animations.AnimatorController>(Folder+"/Clock.controller");var view=actor.GetComponent<FighterView>();var field=typeof(FighterView).GetField("nativeClips",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);var clips=((FighterView.NativeClip[])field.GetValue(view)).ToArray();for(int i=0;i<clips.Length;i++)if(clips[i].state=="Dance")clips[i].clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(Folder+"/Dance.clock.anim");view.UseNativeMotion(clips);if(Mathf.Abs(view.PreviewDuration("Dance")-component.source.duration)>.0001f)throw new Exception("Dance lifecycle carrier does not retain full source duration");
   for(int i=0;i<nodes.Length;i++){nodes[i].localPosition=oldP[i];nodes[i].localRotation=oldQ[i];nodes[i].localScale=oldS[i];}
   PrefabUtility.SaveAsPrefabAsset(actor,Folder+"/Review.exact-generic.prefab");AssetDatabase.SaveAssets();
  }finally{foreach(var b in actor.GetComponents<MonoBehaviour>())if(b is IActorCurveWarmup w)w.Dispose();UnityEngine.Object.DestroyImmediate(actor);}
  Parity();
 }
 public static void Parity(){
  var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/Review.exact-generic.prefab");var candidate=(GameObject)PrefabUtility.InstantiatePrefab(prefab);var independent=(GameObject)PrefabUtility.InstantiatePrefab(prefab);var raw=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Source));
  try{
   foreach(var a in new[]{candidate,independent,raw}){foreach(var b in a.GetComponentsInChildren<MonoBehaviour>(true))b.enabled=false;var animator=a.GetComponentInChildren<Animator>();if(animator)animator.enabled=false;}
   var actual=candidate.GetComponent<ExactGenericDanceRetarget>();var oracle=independent.GetComponent<ExactGenericDanceRetarget>();var sourceBones=Names.Select(n=>raw.GetComponentsInChildren<Transform>(true).Single(t=>t.name==n)).ToArray();var clip=AssetDatabase.LoadAllAssetsAtPath(Source).OfType<AnimationClip>().Single(c=>!c.name.StartsWith("__preview"));
   double maxAngle=0;float maxPosition=0;int samples=Mathf.CeilToInt(clip.length*317);var rows=new List<string>{"seconds,maxLocalRotationDeltaDeg,maxWorldBonePositionDeltaM"};
   foreach(float yaw in new[]{0f,90f,-90f,170f}){Vector3 rootPosition=yaw==0?Vector3.zero:new Vector3(.83f,.17f,-.41f);float rootScale=yaw==-90?1.3f:yaw==90?.7f:1;foreach(var a in new[]{candidate,independent}){a.transform.position=rootPosition;a.transform.rotation=Quaternion.Euler(0,yaw,0);a.transform.localScale=Vector3.one*rootScale;}
   for(int k=0;k<=samples;k++){float seconds=clip.length*k/samples;actual.EvaluateForReview(seconds);clip.SampleAnimation(raw,seconds);for(int n=0;n<oracle.targetNodes.Length;n++){var t=oracle.targetNodes[n];t.localPosition=oracle.targetLocalPositions[n];t.localRotation=oracle.targetLocalRotations[n];t.localScale=oracle.targetLocalScales[n];}
    Vector3 hip=oracle.targetHipRest+oracle.bodyAlignment*(sourceBones[0].position-oracle.sourceHipRest)*oracle.hipHeightScale;hip.x=oracle.targetHipRest.x;hip.z=oracle.targetHipRest.z;oracle.targetMapped[0].position=independent.transform.TransformPoint(hip);
    for(int b=0;b<oracle.targetMapped.Length;b++)oracle.targetMapped[b].rotation=independent.transform.rotation*oracle.bodyAlignment*sourceBones[b].rotation*Quaternion.Inverse(oracle.sourceRestRotations[b])*Quaternion.Inverse(oracle.bodyAlignment)*oracle.targetCanonicalRotations[b];
    double angle=0;float position=0;for(int n=0;n<actual.targetNodes.Length;n++){angle=Math.Max(angle,Angle(actual.targetNodes[n].localRotation,oracle.targetNodes[n].localRotation));position=Mathf.Max(position,Vector3.Distance(actual.targetNodes[n].position,oracle.targetNodes[n].position));}maxAngle=Math.Max(maxAngle,angle);maxPosition=Mathf.Max(maxPosition,position);rows.Add(yaw+":"+seconds+","+angle+","+position);
    if(candidate.transform.position!=rootPosition||Quaternion.Angle(candidate.transform.rotation,Quaternion.Euler(0,yaw,0))>.001f||candidate.transform.localScale!=Vector3.one*rootScale)throw new Exception("Dance overwrote actor world transform");
   }}
   string output="../art/source/unique-dances-20261018/audit/generic-sailor";File.WriteAllLines(output+"/direct-runtime-independent-parity.csv",rows);File.WriteAllText(output+"/direct-runtime-summary.txt","rootYawCases=0,90,-90,170 scales=1,.7,1.3,1 samples="+((samples+1)*4)+" maxLocalAngleDeg="+maxAngle+" maxWorldPositionM="+maxPosition+" sourceNodes="+actual.sourceRoot.GetComponentsInChildren<Transform>(true).Length+" sourceRenderers="+actual.sourceRoot.GetComponentsInChildren<Renderer>(true).Length);if(maxAngle>.06||maxPosition>.00001f)throw new Exception("Direct runtime vs independent Generic FK failed "+maxAngle+" "+maxPosition);Debug.Log("AGENT_RESULT exact Generic dance runtime independent FK parity passed; visual/player gate pending");
  }finally{foreach(var a in new[]{candidate,independent,raw}){foreach(var b in a.GetComponents<MonoBehaviour>())if(b is IActorCurveWarmup w)w.Dispose();UnityEngine.Object.DestroyImmediate(a);}}
 }
 static Transform Clone(Transform from,Transform parent){var t=new GameObject(from.name).transform;t.SetParent(parent,false);t.localPosition=from.localPosition;t.localRotation=from.localRotation;t.localScale=from.localScale;foreach(Transform child in from)if(!child.GetComponent<Renderer>())Clone(child,t);return t;}
 static Quaternion Basis(Transform l,Transform r,Transform h,Transform hip){Vector3 up=(h.position-hip.position).normalized,right=(r.position-l.position).normalized;return Quaternion.LookRotation(Vector3.Cross(right,up).normalized,up);}
 static double Angle(Quaternion a,Quaternion b){double d=(double)a.x*b.x+(double)a.y*b.y+(double)a.z*b.z+(double)a.w*b.w,aa=(double)a.x*a.x+(double)a.y*a.y+(double)a.z*a.z+(double)a.w*a.w,bb=(double)b.x*b.x+(double)b.y*b.y+(double)b.z*b.z+(double)b.w*b.w;return 2*Math.Acos(Math.Min(1,Math.Abs(d)/Math.Sqrt(aa*bb)))*180/Math.PI;}
}
